package com.mg.fixturecockpitsim.visual;
import java.util.*;
/** Procedural modern fighter. AVM-9.5 adds readable side-view landing gear with tyres, hubs, braces and doors. */
public final class ProceduralFighterMesh {
 public static final float PART_SKIN=0,PART_CANOPY=1,PART_NOZZLE=2,PART_INTAKE=3,PART_STAB_L=4,PART_STAB_R=5,PART_RUDDER_L=6,PART_RUDDER_R=7,PART_AFTERBURNER=8,PART_FLAPERON_L=9,PART_FLAPERON_R=10,PART_CANOPY_FRAME=11,PART_NOZZLE_INNER=12,PART_GEAR_STRUT=13,PART_GEAR_WHEEL=14,PART_GEAR_DOOR=15,PART_COCKPIT_TUB=16,PART_SEAT=17,PART_COAMING=18,PART_INTAKE_DUCT=19,PART_COMPRESSOR_FACE=20,PART_NOZZLE_PETAL=21,PART_FLAME_CORE=22,PART_UPPER_PANEL=23,PART_GEAR_HUB=24;
 public static final class Mesh{public final float[] data;public Mesh(float[]d){if(d==null||d.length%7!=0)throw new IllegalStateException("Mesh vertex stride corrupted");data=d;}public int vertexCount(){return data.length/7;}}
 private final List<Float> out=new ArrayList<>();private float part;
 public static Mesh build(){ProceduralFighterMesh b=new ProceduralFighterMesh();b.part=PART_SKIN;b.fuselage();b.wings();b.tails();b.engines();b.part=PART_COCKPIT_TUB;b.cockpitTub();b.part=PART_SEAT;b.ejectionSeat();b.part=PART_COAMING;b.instrumentCoaming();b.part=PART_CANOPY;b.canopy();b.part=PART_CANOPY_FRAME;b.canopyFrame();b.part=PART_GEAR_STRUT;b.gearStruts();b.part=PART_GEAR_WHEEL;b.gearWheels();b.part=PART_GEAR_HUB;b.gearHubs();b.part=PART_GEAR_DOOR;b.gearDoors();float[]d=new float[b.out.size()];for(int i=0;i<d.length;i++)d[i]=b.out.get(i);return new Mesh(d);}
 private void fuselage(){float[]z={-6.2f,-5.4f,-4.5f,-3.5f,-2.5f,-1.4f,-.2f,1,2.1f,3.15f};float[]rx={.05f,.20f,.42f,.72f,1.02f,1.18f,1.26f,1.24f,1.08f,.70f};float[]ry={.05f,.16f,.30f,.48f,.62f,.70f,.72f,.68f,.58f,.40f};for(int s=0;s<z.length-1;s++)for(int i=0;i<24;i++){double a=2*Math.PI*i/24,b=2*Math.PI*(i+1)/24;quad(v(rx[s]*cos(a),.05f+ry[s]*sin(a),z[s]),v(rx[s+1]*cos(a),.05f+ry[s+1]*sin(a),z[s+1]),v(rx[s+1]*cos(b),.05f+ry[s+1]*sin(b),z[s+1]),v(rx[s]*cos(b),.05f+ry[s]*sin(b),z[s]));}part=PART_UPPER_PANEL;prism(new float[][]{{-.48f,.61f,-2.8f},{.48f,.61f,-2.8f},{.75f,.80f,-1.4f},{.74f,.82f,.5f},{.50f,.67f,2.5f},{-.50f,.67f,2.5f},{-.74f,.82f,.5f},{-.75f,.80f,-1.4f}},.06f);part=PART_SKIN;}
 private void wings(){prism(new float[][]{{-.85f,.24f,-1.9f},{-4.35f,.15f,-.10f},{-4.0f,.14f,.75f},{-1.05f,.20f,.45f}},.20f);prism(new float[][]{{.85f,.24f,-1.9f},{4.35f,.15f,-.10f},{4.0f,.14f,.75f},{1.05f,.20f,.45f}},.20f);}
 private void tails(){part=PART_STAB_L;prism(new float[][]{{-.7f,.25f,1.65f},{-2.9f,.22f,2.15f},{-2.25f,.20f,3.25f},{-.75f,.22f,2.85f}},.16f);part=PART_STAB_R;prism(new float[][]{{.7f,.25f,1.65f},{2.9f,.22f,2.15f},{2.25f,.20f,3.25f},{.75f,.22f,2.85f}},.16f);part=PART_RUDDER_L;prism(new float[][]{{-.62f,.52f,1.55f},{-.82f,1.45f,1.8f},{-1.20f,2.35f,2.2f},{-.95f,.50f,3.05f}},.08f);part=PART_RUDDER_R;prism(new float[][]{{.62f,.52f,1.55f},{.82f,1.45f,1.8f},{1.20f,2.35f,2.2f},{.95f,.50f,3.05f}},.08f);part=PART_SKIN;}
 private void engines(){for(float x:new float[]{-.7f,.7f}){part=PART_NOZZLE;ring(x,-.10f,3.05f,.48f,.36f,.55f);part=PART_NOZZLE_INNER;ring(x,-.10f,3.48f,.30f,.23f,.40f);part=PART_AFTERBURNER;cone(x,-.10f,3.82f,5.0f,.20f,.025f);}part=PART_SKIN;}
 private void cockpitTub(){prism(new float[][]{{-.43f,.75f,-1.78f},{.43f,.75f,-1.78f},{.46f,.77f,-.36f},{.37f,.76f,.50f},{-.37f,.76f,.50f},{-.46f,.77f,-.36f}},.22f);}
 private void ejectionSeat(){box(0,.77f,.05f,.34f,.31f,.48f);box(0,1.04f,.30f,.28f,.16f,.18f);}
 private void instrumentCoaming(){prism(new float[][]{{-.38f,.87f,-1.80f},{.38f,.87f,-1.80f},{.31f,.95f,-1.35f},{-.31f,.95f,-1.35f}},.08f);}
 private void canopy(){float[]z={-2.18f,-1.7f,-1.05f,-.35f,.30f,.84f},rx={.38f,.50f,.56f,.54f,.42f,.23f},base={.78f,.81f,.83f,.84f,.82f,.79f},crown={.94f,1.10f,1.22f,1.25f,1.12f,.94f};for(int s=0;s<z.length-1;s++)for(int i=0;i<14;i++){double a=Math.PI*i/14,b=Math.PI*(i+1)/14;quad(v(rx[s]*cos(a),base[s]+(crown[s]-base[s])*sin(a),z[s]),v(rx[s+1]*cos(a),base[s+1]+(crown[s+1]-base[s+1])*sin(a),z[s+1]),v(rx[s+1]*cos(b),base[s+1]+(crown[s+1]-base[s+1])*sin(b),z[s+1]),v(rx[s]*cos(b),base[s]+(crown[s]-base[s])*sin(b),z[s]));}}
 private void canopyFrame(){prism(new float[][]{{-.43f,.80f,-2.15f},{.43f,.80f,-2.15f},{.38f,.90f,-1.94f},{-.38f,.90f,-1.94f}},.05f);prism(new float[][]{{-.51f,.83f,-1.05f},{.51f,.83f,-1.05f},{.45f,.98f,-.88f},{-.45f,.98f,-.88f}},.045f);prism(new float[][]{{-.52f,.79f,-2.02f},{-.43f,.82f,.62f},{-.36f,.79f,.82f},{-.46f,.77f,-2.02f}},.04f);prism(new float[][]{{.46f,.77f,-2.02f},{.36f,.79f,.82f},{.43f,.82f,.62f},{.52f,.79f,-2.02f}},.04f);}
 private void gearStruts(){// nose oleo + fork
  box(0,-1.23f,-3.72f,.16f,.88f,.16f);box(-.12f,-1.58f,-3.72f,.07f,.38f,.10f);box(.12f,-1.58f,-3.72f,.07f,.38f,.10f);
  // main oleos, diagonal drag braces and wheel forks
  for(float s:new float[]{-1,1}){float x=1.48f*s;box(x,-1.20f,.72f,.20f,.92f,.20f);brace(.92f*s,-.58f,.42f,x,-1.34f,.86f,.10f);brace(1.18f*s,-.74f,1.12f,x,-1.34f,.86f,.08f);box(1.62f*s,-1.55f,1.10f,.10f,.34f,.38f);}}
 private void gearWheels(){wheel(0,-1.70f,-3.72f,.31f,.24f);wheel(-1.72f,-1.72f,1.12f,.43f,.31f);wheel(1.72f,-1.72f,1.12f,.43f,.31f);}
 private void gearHubs(){disc(0,-1.70f,-3.72f,.15f,.255f);disc(-1.72f,-1.72f,1.12f,.21f,.325f);disc(1.72f,-1.72f,1.12f,.21f,.325f);}
 private void gearDoors(){prism(new float[][]{{-.31f,-.51f,-4.18f},{-.03f,-.51f,-4.18f},{-.03f,-.51f,-3.22f},{-.31f,-.51f,-3.22f}},.035f);prism(new float[][]{{.03f,-.51f,-4.18f},{.31f,-.51f,-4.18f},{.31f,-.51f,-3.22f},{.03f,-.51f,-3.22f}},.035f);prism(new float[][]{{-1.84f,-.51f,.20f},{-.86f,-.51f,.20f},{-.86f,-.51f,1.58f},{-1.84f,-.51f,1.58f}},.04f);prism(new float[][]{{.86f,-.51f,.20f},{1.84f,-.51f,.20f},{1.84f,-.51f,1.58f},{.86f,-.51f,1.58f}},.04f);}
 private void brace(float x0,float y0,float z0,float x1,float y1,float z1,float t){float mx=(x0+x1)/2,my=(y0+y1)/2,mz=(z0+z1)/2;float dx=x1-x0,dy=y1-y0,dz=z1-z0;float len=(float)Math.sqrt(dx*dx+dy*dy+dz*dz);box(mx,my-len*.5f,mz,t,len,t);}
 private void wheel(float x,float y,float z,float r,float width){int n=24;float x0=x-width/2,x1=x+width/2;for(int i=0;i<n;i++){double a=2*Math.PI*i/n,b=2*Math.PI*(i+1)/n;quad(v(x0,y+r*cos(a),z+r*sin(a)),v(x1,y+r*cos(a),z+r*sin(a)),v(x1,y+r*cos(b),z+r*sin(b)),v(x0,y+r*cos(b),z+r*sin(b)));}}
 private void disc(float x,float y,float z,float r,float width){int n=20;float x0=x-width/2,x1=x+width/2;for(float xx:new float[]{x0,x1})for(int i=0;i<n;i++){double a=2*Math.PI*i/n,b=2*Math.PI*(i+1)/n;tri(v(xx,y,z),v(xx,y+r*cos(a),z+r*sin(a)),v(xx,y+r*cos(b),z+r*sin(b)));}}
 private void ring(float x,float y,float z,float r0,float r1,float dz){for(int i=0;i<24;i++){double a=2*Math.PI*i/24,b=2*Math.PI*(i+1)/24;quad(v(x+r0*cos(a),y+r0*.6f*sin(a),z),v(x+r1*cos(a),y+r1*.6f*sin(a),z+dz),v(x+r1*cos(b),y+r1*.6f*sin(b),z+dz),v(x+r0*cos(b),y+r0*.6f*sin(b),z));}}
 private void cone(float x,float y,float z0,float z1,float r0,float r1){for(int i=0;i<18;i++){double a=2*Math.PI*i/18,b=2*Math.PI*(i+1)/18;quad(v(x+r0*cos(a),y+r0*.55f*sin(a),z0),v(x+r1*cos(a),y+r1*sin(a),z1),v(x+r1*cos(b),y+r1*sin(b),z1),v(x+r0*cos(b),y+r0*.55f*sin(b),z0));}}
 private void box(float x,float y,float z,float sx,float sy,float sz){float hx=sx/2,hz=sz/2;prism(new float[][]{{x-hx,y+sy,z-hz},{x+hx,y+sy,z-hz},{x+hx,y+sy,z+hz},{x-hx,y+sy,z+hz}},sy);}
 private void prism(float[][]top,float th){if(top.length<3)return;float[][]bot=new float[top.length][3];for(int i=0;i<top.length;i++)bot[i]=v(top[i][0],top[i][1]-th,top[i][2]);for(int i=1;i<top.length-1;i++){tri(top[0],top[i],top[i+1]);tri(bot[0],bot[i+1],bot[i]);}for(int i=0;i<top.length;i++)quad(top[i],bot[i],bot[(i+1)%top.length],top[(i+1)%top.length]);}
 private void quad(float[]a,float[]b,float[]c,float[]d){tri(a,b,c);tri(a,c,d);}private void tri(float[]a,float[]b,float[]c){float ux=b[0]-a[0],uy=b[1]-a[1],uz=b[2]-a[2],vx=c[0]-a[0],vy=c[1]-a[1],vz=c[2]-a[2],nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx,l=(float)Math.sqrt(nx*nx+ny*ny+nz*nz);if(l<1e-6)l=1;emit(a,nx/l,ny/l,nz/l);emit(b,nx/l,ny/l,nz/l);emit(c,nx/l,ny/l,nz/l);}private void emit(float[]p,float nx,float ny,float nz){out.add(p[0]);out.add(p[1]);out.add(p[2]);out.add(nx);out.add(ny);out.add(nz);out.add(part);}private static float[]v(double x,double y,double z){return new float[]{(float)x,(float)y,(float)z};}private static float sin(double x){return(float)Math.sin(x);}private static float cos(double x){return(float)Math.cos(x);}
}
